using Microsoft.AspNetCore.Identity.EntityFrameworkCore; using Microsoft.EntityFrameworkCore; using InventorySystem.Application.Interfaces; using InventorySystem.Domain.Entities;
namespace InventorySystem.Infrastructure.Persistence;
public class AppDbContext(DbContextOptions<AppDbContext> options) : IdentityDbContext<AppUser>(options), IAppDbContext { public DbSet<Product> Products=>Set<Product>(); public DbSet<Category> Categories=>Set<Category>(); public DbSet<Warehouse> Warehouses=>Set<Warehouse>(); public DbSet<StockItem> StockItems=>Set<StockItem>(); public DbSet<StockMovement> StockMovements=>Set<StockMovement>(); public DbSet<Supplier> Suppliers=>Set<Supplier>(); protected override void OnModelCreating(ModelBuilder b){ base.OnModelCreating(b); b.Entity<Product>().HasIndex(x=>x.SKU).IsUnique(); b.Entity<Product>().Property(x=>x.PurchasePrice).HasPrecision(18,2); b.Entity<Product>().Property(x=>x.SellingPrice).HasPrecision(18,2); b.Entity<Product>().HasOne(x=>x.Category).WithMany(x=>x.Products).HasForeignKey(x=>x.CategoryId).OnDelete(DeleteBehavior.Restrict); b.Entity<StockItem>().HasIndex(x=>new{x.ProductId,x.WarehouseId}).IsUnique(); b.Entity<StockItem>().HasOne(x=>x.Product).WithMany(x=>x.StockItems).HasForeignKey(x=>x.ProductId); b.Entity<StockItem>().HasOne(x=>x.Warehouse).WithMany(x=>x.StockItems).HasForeignKey(x=>x.WarehouseId); b.Entity<StockMovement>().HasOne(x=>x.Product).WithMany(x=>x.StockMovements).HasForeignKey(x=>x.ProductId).OnDelete(DeleteBehavior.Restrict); b.Entity<StockMovement>().HasOne(x=>x.Warehouse).WithMany().HasForeignKey(x=>x.WarehouseId).OnDelete(DeleteBehavior.Restrict); } }


